insert into public.iniziative
  (id, tipo, titolo, sommario, immagine, data, data_testo, ora, luogo, stato, in_evidenza, testo, link, donazione, pubblicato, creato_da)
values
('raccolta-firme-legge-popolare-2026', 'iniziativa', 'Una legge di iniziativa popolare contro la droga', 'Nella Giornata internazionale contro le droghe la Comunità ha lanciato una raccolta firme nazionale, con mille banchetti nelle piazze italiane.', 'https://www.lautari.it/wp-content/uploads/2018/10/formazione-e-prevenzione-lautari.jpg', '2026-06-26', null, null, null, 'In corso', true, '["Il 26 giugno 2026, Giornata internazionale contro l''abuso e il traffico illecito di droga, il presidente Andrea Bonomelli ha presentato una proposta di legge di iniziativa popolare e una mobilitazione nazionale per raccogliere le firme.", {"titolo": "I punti della proposta"}, {"elenco": ["Pene più severe per gli spacciatori", "Eliminazione della \"modica quantità\" che si può detenere", "Un piano nazionale di sostegno economico e amministrativo per il reinserimento degli ex tossicodipendenti", "Programmi di formazione e supporto per le famiglie, con il coinvolgimento stabile delle comunità terapeutiche"]}, "La raccolta firme passa da mille banchetti nelle principali città italiane. L''appello è rivolto a tutte le forze politiche."]'::jsonb, '{"testo": "Leggi la notizia su ANSA", "url": "https://www.ansa.it/lombardia/notizie/2026/06/27/la-comunita-lautari-lancia-legge-popolare-su-droga-per-abolire-modica-quantita_0998db70-a233-43cd-80cb-16a7ef03f8e6.html"}'::jsonb, null, true, 'sito'),
('olimpiadi-della-vita-2026', 'evento', 'Olimpiadi della Vita 2026: trent''anni di sport e rinascita', 'Dal 10 al 20 agosto, a Borgo La Caccia, circa 300 ragazzi delle sedi Lautari si sono sfidati nella 30ª edizione.', 'https://www.lautari.it/wp-content/uploads/2018/09/vita-in-comunita-lautari-02.jpg', '2026-08-10', null, null, 'Borgo La Caccia, Pozzolengo (BS)', null, true, '["Le Olimpiadi della Vita sono l''appuntamento sportivo dell''estate in comunità. Nel 2026 hanno compiuto trent''anni: dal 10 al 20 agosto circa 300 partecipanti, arrivati dalle sedi di Pozzolengo, Bedizzole, Como, Pordenone, Roma e Firenze, si sono ritrovati alla tenuta di Borgo La Caccia.", {"titolo": "Le discipline"}, {"elenco": ["Calcio e pallavolo", "Padel e biliardo", "Ciclismo e nuoto", "Atletica e maratone di 21 e 32 km"]}, "Il tema dell''edizione era l''antica Grecia, con il motto \"conosci te stesso\". Il programma è stato presentato a Palazzo Broletto, sede della Provincia di Brescia, con il patrocinio della Provincia e del Comune di Pozzolengo. I vincitori potranno partecipare alla Maratona di Marrakech."]'::jsonb, '{"testo": "Leggi l''articolo su La Voce del Popolo", "url": "https://www.lavocedelpopolo.it/index.php/garda-e-valsabbia/le-olimpiadi-della-vita-con-la-comunita-lautari"}'::jsonb, null, true, 'sito'),
('lautari-in-festa-2026', 'evento', 'Lautari in Festa', 'La festa annuale della comunità a Borgo La Caccia: famiglie, operatori, amici e istituzioni insieme ai ragazzi.', 'https://www.lautari.it/wp-content/uploads/2018/10/sede-brescia-lautari-comunita.jpg', '2026-04-18', null, null, 'Borgo La Caccia, Pozzolengo (BS)', null, false, '["Ogni primavera la comunità apre le porte della tenuta di Borgo La Caccia per la sua festa. Nel 2026 si è svolta sabato 18 aprile.", "All''edizione 2025 hanno partecipato oltre mille persone tra famiglie, operatori, amici e istituzioni. Durante la festa sono stati premiati i protagonisti delle Olimpiadi della Vita ed è stata presentata la mostra \"Ho bisogno di me\"."]'::jsonb, '{"testo": "Leggi l''articolo su Il Giorno (edizione 2025)", "url": "https://www.ilgiorno.it/brescia/cronaca/lautari-in-festa-con-ospiti-09cb54b2"}'::jsonb, null, true, 'sito'),
('mostra-ho-bisogno-di-me', 'iniziativa', '"Ho bisogno di me, scatti di indipendenza": la mostra', '33 fotografie sulla vita in comunità, esposte al Senato, al Pirellone di Milano e al Parlamento europeo di Strasburgo.', 'https://www.lautari.it/wp-content/uploads/2018/09/chi-siamo-lautari-comunita-02.jpg', '2024-12-11', null, null, null, null, true, '["\"Ho bisogno di me, scatti di indipendenza\" è una mostra fotografica itinerante di 33 immagini di Beppe e Milla Prandelli, realizzate in due anni dentro la comunità. Le stesse foto compongono il calendario 2025 della Comunità Lautari, pubblicato per i suoi 33 anni.", {"titolo": "Le tappe"}, {"elenco": ["Roma, Senato della Repubblica, Sala Zuccari di Palazzo Giustiniani: inaugurazione l''11 dicembre 2024", "Milano, Pirellone (Consiglio regionale della Lombardia): dal 22 aprile all''8 maggio 2025", "Strasburgo, Parlamento europeo: una selezione di 13 fotografie"]}, "La mostra accompagna il libro \"Ho bisogno di me\" curato da Giuseppe Spatola."]'::jsonb, '{"testo": "Leggi l''articolo su Il Giorno", "url": "https://www.ilgiorno.it/brescia/cultura/mostra-ho-bisogno-di-me-scatti-indipendenza-vgplvrjj"}'::jsonb, null, true, 'sito'),
('drug-zero', 'progetto', 'Drug Zero', 'Prevenzione nelle scuole: la comunità entra in classe e le classi vengono in comunità, per prevenire l''uso di sostanze e informare sulle conseguenze.', 'https://www.lautari.it/wp-content/uploads/2018/10/formazione-e-prevenzione-lautari.jpg', null, null, null, null, 'In corso', false, '["Drug Zero porta nelle scuole l''esperienza diretta della comunità. Gli obiettivi sono due: prevenire l''uso di sostanze e informare con chiarezza sulle loro conseguenze.", {"titolo": "Noi da voi: la comunità a scuola"}, "Un incontro di circa due ore in classe con operatori e ragazzi della comunità. Il costo è una donazione liberale più il rimborso del viaggio.", {"titolo": "Voi da noi: la scuola in comunità"}, "Una giornata nella sede di Pozzolengo, dalle 10:00 alle 16:30, per vedere da vicino la vita in comunità. Il costo è di 10 € a persona, pasti inclusi.", "Per informazioni: Dott.ssa Glenda Orlandi, assistente sociale, al numero 030 991 8700."]'::jsonb, null, 'drug-zero', true, 'sito'),
('salvagente', 'progetto', 'Salvagente', 'Accoglienza residenziale per persone in forte svantaggio sociale: disoccupati di lungo periodo, genitori soli, over 40 espulsi dal lavoro, donne che hanno subito maltrattamenti.', 'https://www.lautari.it/wp-content/uploads/2018/09/il-percorso-in-comunita-02.jpg', null, null, null, null, 'In corso', false, '["Salvagente offre un posto sicuro a chi attraversa un momento di grave difficoltà, anche senza una storia di dipendenza.", {"titolo": "A chi si rivolge"}, {"elenco": ["Disoccupati di lungo periodo", "Adulti soli con figli", "Persone over 40 espulse dal mondo del lavoro", "Persone con difficoltà abitative", "Donne con precedenti di maltrattamenti"]}, {"titolo": "Obiettivi"}, {"elenco": ["Accoglienza residenziale", "Integrazione nelle attività della comunità", "Prevenzione della cronicizzazione dei disturbi dell''umore", "Reinserimento sociale"]}, "Si accede su segnalazione dei Servizi Sociali del Comune di residenza. L''accoglienza dura 6 mesi, prorogabili di altri 6."]'::jsonb, null, 'salvagente', true, 'sito'),
('grest', 'progetto', 'Grest', 'Prevenzione e informazione sulla droga per animatori e ragazzi dei centri estivi parrocchiali, e per i loro genitori.', 'https://www.lautari.it/wp-content/uploads/2018/10/sport-vita-in-comunita-02.jpg', null, null, null, null, 'In corso', false, '["Il progetto Grest porta la prevenzione nei centri estivi parrocchiali, rivolgendosi ad animatori, ragazzi e genitori.", {"titolo": "Noi da voi"}, "Un incontro di circa due ore con un gruppo di 20-30 ragazzi. Il contributo è a discrezione, con rimborso delle spese.", {"titolo": "Voi da noi"}, "Una giornata nella sede di Pozzolengo, dalle 10:00 alle 16:30, a 10 € a persona, pasti inclusi."]'::jsonb, null, 'grest', true, 'sito'),
('prevenzione-e-informazione', 'progetto', 'Prevenzione e informazione', 'Le testimonianze dei ragazzi in parrocchie, scuole e centri giovanili: chi sta facendo il percorso racconta la propria storia.', 'https://www.lautari.it/wp-content/uploads/2018/09/vita-in-comunita-lautari-02.jpg', null, null, null, null, 'In corso', false, '["La prevenzione e l''informazione sono una delle eccellenze della nostra struttura. I ragazzi portano la loro testimonianza in parrocchie, scuole e centri giovanili.", {"titolo": "Perché lo facciamo"}, {"elenco": ["Capacità relazionali: parlare in pubblico della propria storia aiuta i ragazzi a crescere", "Raccolta fondi: incontrare persone che credono nel nostro progetto e scelgono di sostenerlo", "Reinserimento: creare legami con il territorio"]}]'::jsonb, null, 'prevenzione', true, 'sito'),
('aiuti-alimentari-2025', 'collaborazione', 'Aiuti alimentari con il Banco Alimentare della Lombardia', 'Nel 2025, con il programma PN Inclusione, abbiamo sostenuto 110 persone in grave deprivazione distribuendo 96.030 tra pacchi e pasti.', 'https://www.lautari.it/wp-content/uploads/2018/09/chi-siamo-lautari-comunita-02.jpg', '2025-12-31', 'Anno 2025', null, null, null, false, '["Nel 2025 la Comunità ha partecipato alla distribuzione di aiuti alimentari del programma PN Inclusione, con capofila il Banco Alimentare della Lombardia \"Danilo Fossati\" ODV.", {"titolo": "I numeri del 2025"}, {"elenco": ["110 persone in condizione di grave deprivazione sostenute", "3.224 kg di prodotti alimentari", "96.030 pacchi e/o pasti distribuiti"]}]'::jsonb, null, null, true, 'sito'),
('borgo-la-caccia', 'collaborazione', 'Borgo la Caccia ed Eno Caccia', 'Cantina, vigneto e allevamento di cavalli sulle colline moreniche del Garda: il lavoro che diventa reinserimento.', 'https://www.lautari.it/wp-content/uploads/2018/09/la-cantina-lautari.png', null, null, null, null, 'Attiva', false, '["La Tenuta Borgo la Caccia, a Pozzolengo, è il luogo dove si svolge gran parte delle attività lavorative della comunità. Si estende per 90 ettari, di cui 30 di vigneti, sulle colline moreniche a ridosso del Lago di Garda.", "Borgo la Caccia Horses nasce all''inizio degli anni ''90 per l''allevamento e la preparazione agonistica di cavalli da salto ostacoli. Borgo la Caccia Wine and Events nasce all''inizio degli anni 2000 ed è parte di Eno Caccia, la cooperativa sociale agricola di reinserimento.", "Qui i ragazzi imparano un mestiere e, finito il percorso, possono essere assunti nelle nostre cooperative di lavoro."]'::jsonb, '{"testo": "Visita borgolacaccia.it", "url": "https://www.borgolacaccia.it/"}'::jsonb, null, true, 'sito'),
('cooperativa-insieme', 'collaborazione', 'Falegnameria e restauro con la Cooperativa Insieme', 'Lavorazioni pregiate in legno, creazioni su misura e restauri: un mestiere vero per chi esce dal percorso.', 'https://www.lautari.it/wp-content/uploads/2018/09/il-restauro-lautari.png', null, null, null, null, 'Attiva', false, '["Con la Cooperativa Insieme Onlus i ragazzi lavorano in falegnameria e nel restauro: lavorazioni pregiate in legno, creazioni su misura e restauri.", "È una delle cooperative di reinserimento in cui gli ex ospiti possono trovare lavoro al termine del percorso."]'::jsonb, null, null, true, 'sito'),
('nuova-sede-pozzolengo', 'iniziativa', 'La nuova sede di Pozzolengo', 'Inaugurata a fine 2015 in Via Monte Ingrana, è stata costruita grazie al sostegno di tanti amici della comunità.', 'https://www.lautari.it/wp-content/uploads/2018/10/sede-brescia-lautari-comunita.jpg', '2015-12-01', 'Fine 2015', null, null, null, false, '["La nuova sede centrale di Via Monte Ingrana 2, a Pozzolengo (BS), è stata inaugurata a fine 2015. È uno dei progetti portati avanti dal presidente Andrea Bonomelli.", "Ringraziamo tutti i sostenitori che con il loro aiuto l''hanno resa possibile."]'::jsonb, null, null, true, 'sito')
