-- Contenuti iniziali: gli stessi di contenuti/iniziative.json.
-- Si può eseguire più volte: aggiorna le voci esistenti con lo stesso id.
on conflict (id) do update set
  tipo = excluded.tipo, titolo = excluded.titolo, sommario = excluded.sommario,
  immagine = excluded.immagine, data = excluded.data, data_testo = excluded.data_testo,
  ora = excluded.ora, luogo = excluded.luogo, stato = excluded.stato,
  in_evidenza = excluded.in_evidenza, testo = excluded.testo, link = excluded.link,
  donazione = excluded.donazione;
